namespace RisingLands;
public static class ConstructionTests {
    static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);}
    public static void Run(string root){var visuals=new VisualCatalog();World Load(){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE01.ETA"));visuals.Apply(w);for(int i=0;i<65536;i++)if(i!=5642&&Math.Abs((i&255)-10)+Math.Abs((i>>8)-22)<=6&&w.Objects[i] is 67 or >=29 and <=52){w.Objects[i]=0;w.Quantities[i]=0;}return w;}Simulation Create()=>new(Load());
        var sim=Create();var builder=sim.World.Units.First(u=>u.Type==7&&u.Owner==0);int site=-1;for(int y=8;y<22&&site<0;y++)for(int x=20;x<29&&site<0;x++)if(sim.PlacementError(builder,3,y*256+x)==null)site=y*256+x;
        Check(site>=0,"free storehouse site exists in first mission");Check(sim.Rule(3).Food==10&&sim.Rule(3).Rock==6&&sim.Rule(3).Width==5&&sim.Rule(3).Height==5,"storehouse uses original cost and footprint");
        Check(!sim.StartConstruction(sim.World.Units.First(u=>u.Type==5),3,site),"farmer cannot construct buildings");Check(sim.StartConstruction(builder,3,site),"builder starts reachable storehouse");Check(sim.World.Resources[0]==20&&sim.World.Resources[4]==24,"construction charged exactly once");
        string before=sim.Serialize();Check(!sim.StartConstruction(builder,3,site)&&sim.Serialize()==before,"overlapping construction rejected without payment or changes");Check(!sim.Passable(site&255,site>>8),"construction site blocks navigation");
        for(int i=0;i<10;i++)sim.Step();string saved=sim.Serialize();var other=Create();other.Restore(saved);for(int i=0;i<2000;i++){sim.Step();other.Step();}
        Check(sim.Serialize()==other.Serialize(),"construction resumes deterministically after save/load");Check(sim.Constructions.Count==1&&sim.Complete(sim.Constructions[0])&&sim.World.Buildings.Count(b=>b.Type==3)==1,"storehouse completion creates one empty warehouse");
        Check(sim.Rule(3).Collision.Where(i=>!sim.InteractionPassage(site+i)).All(i=>!sim.Passable((site+i)&255,(site+i)>>8)),"completed warehouse blocks its body while admitting the doorway corridor");
        Check(sim.Residents(sim.Constructions[0].Id)==0,"completed warehouse has no invented colonists");var resident=sim.ReleaseResident(sim.World.Buildings.First(b=>b.Type==2&&b.Owner==0).Slot);Check(resident!=null&&sim.EnterBuilding(resident,sim.Constructions[0].Id),"player inhabits new warehouse before delivery");for(int i=0;i<10000&&sim.ResidentTrips.Count>0;i++)sim.Step();
        var farmer=sim.World.Units.First(u=>u.Type==5);Check(sim.SetFoodDestination(farmer,2,sim.Constructions[0].Id)&&sim.Gather(farmer,5642),"collection starts after real warehouse construction");for(int i=0;i<20000&&farmer.FoodJob!=0;i++)sim.Step();Check(sim.World.Resources[0]==34,"constructed warehouse receives all fourteen collected food items");
        var done=Create();done.Restore(sim.Serialize());Check(done.Serialize()==sim.Serialize()&&done.World.Buildings.Count(b=>b.Type==3)==1,"completed building and spent resources survive save/load");
        var paused=Create();var worker=paused.World.Units.First(u=>u.Type==7);paused.StartConstruction(worker,3,site);paused.Order(worker,worker.X/1024,worker.Y/1024);for(int i=0;i<100;i++)paused.Step();Check(paused.Constructions[0].BuilderSlot==-1&&paused.Constructions[0].Progress==0,"movement order pauses construction without losing site");Check(paused.ResumeConstruction(worker,paused.Constructions[0]),"builder resumes paused site without second payment");for(int i=0;i<2000;i++)paused.Step();Check(paused.Complete(paused.Constructions[0])&&paused.World.Resources[0]==20,"resumed construction finishes at original paid cost");
        var groupSim=Create();var group=groupSim.World.Units.Where(u=>u.Type==0&&u.Owner==0).ToArray();int moved=groupSim.OrderGroup(group,12,20);Check(moved==3&&group.Select(u=>u.Route.Last()).Distinct().Count()==3,"group movement assigns distinct reachable destinations");foreach(var unit in group)groupSim.Stop(unit);Check(group.All(u=>u.Route.Count==0),"stop command clears all group routes");var enemy=new Actor{Slot=999,Owner=1,Type=0,LegacyState=7,X=10000,Y=10000};Check(groupSim.OrderGroup(new[]{enemy},12,20)==0,"group commands cannot control enemy units");
        Check(Simulation.BuildData.Buildings.Count==22,"construction catalog contains all twenty-two original building types");
        Check(new[]{1,2,3,4}.All(sim.BuildingUnlocked)&&!sim.BuildingUnlocked(0)&&!sim.BuildingUnlocked(7),"mission one construction list respects original initial technology");
        string locked=sim.Serialize();Check(!sim.StartConstruction(builder,0,site)&&sim.Serialize()==locked,"locked lighthouse cannot consume resources");
        Check(sim.BuildingRequirement(0).Contains("Engenharia"),"locked construction identifies research branch");
        var third=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE03.ETA"));visuals.Apply(third);Check(new Simulation(third).BuildingUnlocked(7),"mission three original technology unlocks laboratory");
        foreach(int type in new[]{1,2,4}){var funded=Load();funded.Resources[0]=100;funded.Resources[4]=100;var extra=new Simulation(funded);var w=extra.World.Units.First(u=>u.Type==7);bool started=false;foreach(int cell in Enumerable.Range(0,65536).Where(c=>(c&255)<extra.World.Width&&(c>>8)<extra.World.Height).OrderBy(c=>Math.Abs((c&255)-w.X/1024)+Math.Abs((c>>8)-w.Y/1024))){if(extra.StartConstruction(w,type,cell)){started=true;break;}}Check(started,"reachable construction for type "+type);for(int i=0;i<10000+extra.Rule(type).Duration*16&&!extra.Complete(extra.Constructions[0]);i++)extra.Step();Check(extra.Constructions.Count==1&&extra.Complete(extra.Constructions[0]),"completion for type "+type);}
    }
}
